head.script:
scwin.parseJwt = function (token) {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function (c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));

        const payload = JSON.parse(jsonPayload);
        return payload;
    } catch (error) {
        return null;
    }
};


scwin.loadModuleData = function (tenantId) {


    dma_moduleRequest.set("tenantId", tenantId);


    $p.executeSubmission("sbm_getModuleList");
};

scwin.btn_refresh_onclick = function () {

    const accessToken = sessionStorage.getItem('accessToken');
    if (accessToken) {
        const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
        const tokenPayload = scwin.parseJwt(tokenString);
        const tokenTenant = tokenPayload ? tokenPayload.tenantId : null;

        if (tokenTenant) {
            scwin.loadModuleData(tokenTenant);
        }
    }
  //  grp_module_detail.hide();
};

scwin.createModuleCards = function(moduleData) {

    try {
        // 1) 컨테이너 DOM 요소 조회 (WebSquare 내 렌더된 div)
        var container = document.querySelector(".card-container");
        if (!container) {
            return;
        }

        // 2) 기존 카드 제거
        container.innerHTML = "";

        // 3) 데이터 순회하며 카드 생성
        moduleData.forEach(function(item, idx) {


            // 카드 래퍼
            var card = document.createElement("div");
            card.className = "module-card";
            card.dataset.moduleId = item.moduleId || "";

            // 아이콘(이모지)
            var emoji = document.createElement("span");
            emoji.className = "module-icon";
            emoji.textContent = item.icon || "–";
            card.appendChild(emoji);

            // 모듈명
            var nameDiv = document.createElement("div");
            nameDiv.className = "module-name";
            nameDiv.textContent = item.name || "이름 없음";
            card.appendChild(nameDiv);

            // 코드
            var codeDiv = document.createElement("div");
            codeDiv.className = "module-code";
            codeDiv.textContent = "(" + (item.code || "") + ")";
            card.appendChild(codeDiv);

            // 설명
            var descDiv = document.createElement("div");
            descDiv.className = "module-desc";
            descDiv.textContent = item.description || "설명 없음";
            card.appendChild(descDiv);

            // 가격·구매일
            var infoDiv = document.createElement("div");
            infoDiv.className = "module-info";
            infoDiv.textContent = "가격: " + (item.price || "-") +
                                  " \n구매일: " + (item.purchasedAt || "-");
            card.appendChild(infoDiv);

            // 상세보기 버튼
            var actionDiv = document.createElement("div");
            actionDiv.className = "card-action";
            var btn = document.createElement("button");
            btn.className = "btn btn-primary";
            btn.style.fontSize = "12px";
            btn.textContent = "상세보기";
            btn.addEventListener("click", function() {
                scwin.showModuleDetails(item.moduleId);
            });
            actionDiv.appendChild(btn);
            card.appendChild(actionDiv);

            // 컨테이너에 추가
            container.appendChild(card);
        });



    } catch (err) {
        console.error("createModuleCards 오류:", err, err.stack);
    }
};

scwin.filterByStatus = function (status) {

    try {
        var dataListComponent = dlt_modules || $p.getComponentById("dlt_modules");
        if (!dataListComponent) {

            return;
        }

        var allData = dataListComponent.getAllJSON();
        scwin.createModuleCards(allData);

    } catch (error) {
        console.error("필터링 중 오류 발생:", error);
    }
};


scwin.showModuleDetails = function (moduleId) {
    dma_moduleId.set("moduleId",moduleId);
    $p.executeSubmission("sbm_getSessionList");
    grp_module_detail.show();

    if (moduleId === '1') {
        dma_selectedModule.set("totalUsage", 128);
        dlt_meetingRooms.setJSON([
            { roomName: "대회의실", lastUsed: "2025-07-20" },
            { roomName: "프로젝트룸 A", lastUsed: "2025-07-21" },
            { roomName: "임원 회의실", lastUsed: "2025-07-18" }
        ]);
    } else if (moduleId === 'mod-002') {
        dma_selectedModule.set("totalUsage", 256);
        dlt_meetingRooms.setJSON([
            { roomName: "소회의실 1", lastUsed: "2025-07-21" },
            { roomName: "프로젝트룸 B", lastUsed: "2025-07-20" },
            { roomName: "고객 접견실", lastUsed: "2025-07-19" }
        ]);
    } else {
        dma_selectedModule.set("totalUsage", 0);
        dlt_meetingRooms.setJSON([]);
    }

    // dlt_modules에서 선택된 모듈의 이름을 찾습니다.
    const selectedModuleRow = dlt_modules.getMatchedIndex("moduleId", moduleId);
    if (selectedModuleRow.length > 0) {
        txt_selected_module_name.setValue(dlt_modules.getCellData(selectedModuleRow[0], "name"));
    } else {
        txt_selected_module_name.setValue("모듈 사용 내역"); // 찾을 수 없는 경우 기본값
    }
};

scwin.deactivateModule = function (moduleId) {
    var rowIndex = dlt_modules.getMatchedIndex("moduleId", moduleId)[0];
    var moduleName = dlt_modules.getCellData(rowIndex, "name");
    if (confirm("'" + moduleName + "' 모듈을 사용 중지하시겠습니까?")) {
        dlt_modules.setCellData(rowIndex, "status", "inactive");
    }
};

scwin.statusFormatter = function (status) {
    return status === 'active' ? 'status-active' : 'status-inactive';
};




// 2. submitdone 함수 수정 (DataList 접근 방법 개선)
scwin.sbm_getModuleList_submitdone = function (e) {

    if (e.responseStatusCode === 200) {
        var actualList = e.responseJSON.tenantModuleDetailVoList.tenantModuleDetailVoList;

        if (actualList && Array.isArray(actualList)) {
            var transformedData = actualList.map(function (item) {
                return {
                    moduleId: item.moduleId || '',
                    name: item.name || '',
                    price: item.price || '',
                    purchasedAt: item.purchasedAt || '',
                    icon: item.icon || '',
                    description: item.description || '',
                    code: item.code || ''
                };
            });


            var dataListComponent = null;
            if (typeof dlt_modules !== 'undefined') {
                dataListComponent = dlt_modules;

            } else if (typeof $p !== 'undefined' && $p.getComponentById) {
                dataListComponent = $p.getComponentById("dlt_modules");

            } else if (typeof $p !== 'undefined' && $p.data) {
                dataListComponent = $p.data.dlt_modules;

            }

            if (dataListComponent && typeof dataListComponent.setJSON === 'function') {

                dataListComponent.setJSON(transformedData);

                scwin.createModuleCards(transformedData);
            }
        }
    }
};  
scwin.sbm_getSessionList_submitdone = function (e) {
// 응답 데이터에서 sessionVoList 추출
    var sessionList = e.responseJSON.sessionVoList;

    // DataList에 설정할 데이터 배열 생성
    var meetingRoomsData = [];

    if (sessionList && sessionList.length > 0) {
        // sessionVoList의 각 항목을 DataList 구조에 맞게 변환
        for (var i = 0; i < sessionList.length; i++) {
            var session = sessionList[i];

            meetingRoomsData.push({
                roomName: session.name,           // name을 roomName으로 매핑
                lastUsed: session.startTime       // startTime을 lastUsed로 매핑
            });
        }
    }

    // DataList에 데이터 설정
    dlt_meetingRooms.setJSON(meetingRoomsData);

    // 총 사용 횟수를 행 개수로 업데이트
    var totalCount = dlt_meetingRooms.getRowCount();
    dma_selectedModule.set("totalUsage", totalCount);


};

scwin.onpageload = function () {
    const accessToken = sessionStorage.getItem('accessToken');
    if (accessToken) {
        const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
        const tokenPayload = scwin.parseJwt(tokenString);
        const tokenTenant = tokenPayload ? tokenPayload.tenantId : null;


        if (tokenTenant) {
            scwin.loadModuleData(tokenTenant);
        } else {
            console.error("tenantId를 찾을 수 없습니다.");
        }
    } else {
        console.error("accessToken을 찾을 수 없습니다.");
    }

    //grp_module_detail.hide();
};
